/**
 * Admin seeding tool for world labels (build plan M25, GDD §6.5, architecture §6.3). The build
 * plan's "generate labels per language once (server, cloud), cache them in cache/labels/{lang}"
 * maps onto the architecture like this: the game server never calls a model, and only the admin
 * seeding tool writes `cache/*`. So this tool publishes one language's labels as the Firestore
 * document `cache/labels/{lang}` with the Admin SDK; players only read it. A key missing there is
 * generated by the client for that player alone (hybrid task `worldLabels`, cloud first) and kept
 * in the player's IndexedDB, never in Firestore.
 *
 *   npm run seed:labels -- --prompts <lang>                          print the generation prompts
 *   npm run seed:labels -- <labels.json>                             dry run: validate, list gaps
 *   npm run seed:labels -- <labels.json> --write --project <id>      publish (admin credentials)
 *
 * The labels file: `{ "lang": "es", "labels": { "<labelKey>": { "word", "reading"?, "audioHash"? } } }`.
 * Every key must be in the shared LABEL_REGISTRY; keys the file lacks are reported (the client
 * generates them per player). Run the printed prompts through the cloud model (`gemini-3.8-flash`)
 * with the `worldLabels` JSON schema and spot-check the answers (GDD §6.5) before writing.
 *
 * TODO(seeding tool, no milestone yet, see pending.md): run the prompts from here with the admin
 * project, and voice the labels (seeded `tts/` clips, `audioHash`).
 */
import { readFile } from "node:fs/promises";
import { resolve } from "node:path";
import { pathToFileURL } from "node:url";
import { z } from "zod";
import {
  type CachedLabels,
  CachedLabelsSchema,
  FirestorePaths,
  getLanguage,
  isLabelKey,
  LABEL_KEYS,
  labelEnglish,
  WORLD_LABELS_BATCH,
  worldLabelsPrompt,
} from "../../packages/shared/src/index";

export const LabelsFileSchema = z.strictObject({
  lang: z.string().min(2).max(20),
  labels: CachedLabelsSchema,
});

export interface LabelsPlan {
  lang: string;
  docPath: string;
  doc: CachedLabels;
  /** Registry keys the file does not have (generated per player on a miss). */
  missing: string[];
}

export function planLabelsSeed(raw: unknown): LabelsPlan {
  const file = LabelsFileSchema.parse(raw);
  if (!getLanguage(file.lang)) throw new Error(`unknown language: ${file.lang}`);
  const unknown = Object.keys(file.labels).filter((k) => !isLabelKey(k));
  if (unknown.length) throw new Error(`unknown label keys: ${unknown.join(", ")}`);
  const missing = LABEL_KEYS.filter((k) => !Object.hasOwn(file.labels, k));
  return { lang: file.lang, docPath: FirestorePaths.cacheEntry("labels", file.lang), doc: file.labels, missing };
}

/** The generation prompts for a language, one per batch of keys. */
export function labelPrompts(lang: string): string[] {
  if (!getLanguage(lang)) throw new Error(`unknown language: ${lang}`);
  const out: string[] = [];
  for (let i = 0; i < LABEL_KEYS.length; i += WORLD_LABELS_BATCH) {
    const items = LABEL_KEYS.slice(i, i + WORLD_LABELS_BATCH).map((key) => ({ key, english: labelEnglish(key) }));
    out.push(worldLabelsPrompt({ targetLang: lang, items }));
  }
  return out;
}

export async function writeLabelsSeed(plan: LabelsPlan, projectId: string): Promise<void> {
  const { initializeApp, applicationDefault } = await import("firebase-admin/app");
  const { getFirestore } = await import("firebase-admin/firestore");
  const emulated = Boolean(process.env.FIRESTORE_EMULATOR_HOST);
  const app = initializeApp(emulated ? { projectId } : { projectId, credential: applicationDefault() }, "hellovalley-seed-labels");
  await getFirestore(app).doc(plan.docPath).set(plan.doc);
  console.log(`seeded ${plan.docPath} (${Object.keys(plan.doc).length} labels)`);
}

function arg(args: readonly string[], name: string): string | undefined {
  const i = args.indexOf(name);
  return i >= 0 ? args[i + 1] : undefined;
}

export async function main(args: readonly string[]): Promise<number> {
  const promptsFor = arg(args, "--prompts");
  if (promptsFor) {
    labelPrompts(promptsFor).forEach((p, i) => console.log(`--- batch ${i + 1}\n${p}\n`));
    return 0;
  }
  const path = args[0];
  if (!path || path.startsWith("--")) {
    console.error("usage: seed-labels --prompts <lang> | <labels.json> [--write --project <id>]");
    return 2;
  }
  const plan = planLabelsSeed(JSON.parse(await readFile(path, "utf8")));
  console.log(`${plan.docPath}: ${Object.keys(plan.doc).length} labels, ${plan.missing.length} missing${plan.missing.length ? ` (${plan.missing.slice(0, 8).join(", ")}…)` : ""}`);
  if (!args.includes("--write")) {
    console.log("dry run: nothing written (add --write --project <id>)");
    return 0;
  }
  const projectId = arg(args, "--project");
  if (!projectId) {
    console.error("--write needs --project <id>");
    return 2;
  }
  if (!process.env.FIRESTORE_EMULATOR_HOST && !process.env.GOOGLE_APPLICATION_CREDENTIALS) {
    console.error("--write needs GOOGLE_APPLICATION_CREDENTIALS (an admin service account) or the emulators");
    return 2;
  }
  await writeLabelsSeed(plan, projectId);
  return 0;
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  main(process.argv.slice(2)).then(
    (code) => process.exit(code),
    (error: unknown) => {
      console.error(error instanceof Error ? error.message : error);
      process.exit(1);
    },
  );
}
